361	@@ -0,0 +1,93 @@
362	+//! Shared timestamp-domain comparisons for bolt-v3 runtime evidence.
363	+
364	+use std::cmp::Ordering;
365	+
366	+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
367	+pub enum TimestampDomain {
368	+    VenueEvent,
369	+    LocalReceive,
370	+    NtStrategyClock,
371	+}
372	+
373	+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
374	+pub struct DomainTimestampMs {
375	+    domain: TimestampDomain,
376	+    value: u64,
377	+}
378	+
379	+impl DomainTimestampMs {
380	+    pub const fn venue_event(value: u64) -> Self {
381	+        Self {
382	+            domain: TimestampDomain::VenueEvent,
383	+            value,
384	+        }
385	+    }
386	+
387	+    pub const fn local_receive(value: u64) -> Self {
388	+        Self {
389	+            domain: TimestampDomain::LocalReceive,
390	+            value,
391	+        }
392	+    }
393	+
394	+    pub const fn nt_strategy_clock(value: u64) -> Self {
395	+        Self {
396	+            domain: TimestampDomain::NtStrategyClock,
397	+            value,
398	+        }
399	+    }
400	+
401	+    pub const fn domain(self) -> TimestampDomain {
402	+        self.domain
403	+    }
404	+
405	+    pub const fn value(self) -> u64 {
406	+        self.value
407	+    }
408	+
409	+    pub fn cmp_same_domain(self, other: Self) -> Option<Ordering> {
410	+        (self.domain == other.domain).then(|| self.value.cmp(&other.value))
411	+    }
412	+
413	+    pub fn eq_same_domain(self, other: Self) -> Option<bool> {
414	+        self.cmp_same_domain(other)
415	+            .map(|ordering| ordering == Ordering::Equal)
416	+    }
417	+
418	+    pub fn lt_same_domain(self, other: Self) -> Option<bool> {
419	+        self.cmp_same_domain(other)
420	+            .map(|ordering| ordering == Ordering::Less)
421	+    }
422	+
423	+    pub fn saturating_duration_since_same_domain(self, earlier: Self) -> Option<u64> {
424	+        (self.domain == earlier.domain).then(|| self.value.saturating_sub(earlier.value))
425	+    }
426	+}
427	+
428	+#[cfg(test)]
429	+mod tests {
430	+    use super::*;
431	+
432	+    #[test]
433	+    fn same_domain_timestamps_compare() {
434	+        let earlier = DomainTimestampMs::venue_event(1_000);
435	+        let later = DomainTimestampMs::venue_event(1_500);
436	+
437	+        assert_eq!(later.cmp_same_domain(earlier), Some(Ordering::Greater));
438	+        assert_eq!(
439	+            later.saturating_duration_since_same_domain(earlier),
440	+            Some(500)
441	+        );
442	+    }
443	+
444	+    #[test]
445	+    fn cross_domain_timestamps_do_not_compare() {
446	+        let event = DomainTimestampMs::venue_event(1_000);
447	+        let receive = DomainTimestampMs::local_receive(1_001);
448	+        let strategy = DomainTimestampMs::nt_strategy_clock(1_002);
449	+
450	+        assert_eq!(event.cmp_same_domain(receive), None);
451	+        assert_eq!(receive.lt_same_domain(strategy), None);
452	+        assert_eq!(strategy.saturating_duration_since_same_domain(event), None);
453	+    }
454	+}
