pub(crate) async fn submit_market_order(
    &self,
    request: MarketOrderSubmitRequest,
) -> anyhow::Result<MarketOrderSubmitResult> {
    let MarketOrderSubmitRequest {
        token_id,
        side,
        amount,
        time_in_force,
        neg_risk,
        tick_decimals,
        fee_context,
    } = request;
    let poly_side = PolymarketOrderSide::try_from(side)
        .map_err(|e| anyhow::anyhow!("Invalid order side: {e}"))?;
    let order_type = PolymarketOrderType::from_market_time_in_force(time_in_force)
        .map_err(|e| anyhow::anyhow!("{e}"))?;
    let amount_dec = amount.as_decimal();

    let book = self
        .http_client
        .get_book(&token_id)
        .await
        .map_err(|e| anyhow::anyhow!("Failed to fetch order book: {e}"))?;

    let levels = match poly_side {
        PolymarketOrderSide::Buy => &book.asks,
        PolymarketOrderSide::Sell => &book.bids,
    };

    let result = calculate_market_price(levels, amount_dec, poly_side)
        .map_err(|e| anyhow::anyhow!("Market price calculation failed: {e}"))?;

    // Fee-aware sizing applies to BUY only and only when a context is
    // provided. Run before signing so the on-chain `taker_amount` and
    // the emitted base quantity both reflect the venue-fillable amount.
    let signed_amount = match (poly_side, fee_context) {
        (PolymarketOrderSide::Buy, Some(ctx)) => adjust_market_buy_amount(
            amount_dec,
            ctx.user_pusd_balance,
            result.crossing_price,
            ctx.fee_rate,
            ctx.fee_exponent,
            ctx.builder_taker_fee_rate,
        )?,
        _ => amount_dec,
    };

    let poly_order = self
        .order_builder
        .build_market_order(
            &token_id,
            poly_side,
            result.crossing_price,
            signed_amount,
            neg_risk,
            tick_decimals,
        )
        .map_err(|e| anyhow::anyhow!("Failed to build market order: {e}"))?;

    // Wire amounts are mantissas at USDC_DECIMALS (10^6) scale. For BUY,
    // the signed taker_amount is the exact share quantity the venue will
    // fill against; for SELL, the original `amount` is already in base
    // shares (book walk total is irrelevant since SELL is never quote-qty).
    let usdc_scale = Decimal::from(1_000_000u32);
    let signed_base_qty = match poly_side {
        PolymarketOrderSide::Buy => poly_order.taker_amount / usdc_scale,
        PolymarketOrderSide::Sell => amount_dec,
    };
    let expected_venue_order_id = self
        .order_builder
        .expected_order_id(&poly_order, neg_risk)?;

    let http_client = self.http_client.clone();

    let response = match self
        .retry_manager
        .execute_with_retry(
            "submit_market_order",
            || {
                let http_client = http_client.clone();
                let poly_order = poly_order.clone();
                async move { http_client.post_order(&poly_order, order_type, false).await }
            },
            |e| e.is_retryable(),
            Error::transport,
        )

pub fn build_market_order(
    &self,
    token_id: &str,
    side: PolymarketOrderSide,
    price: Decimal,
    amount: Decimal,
    neg_risk: bool,
    tick_decimals: u32,
) -> anyhow::Result<PolymarketOrder> {
    let (maker_amount, taker_amount) =
        compute_market_maker_taker_amounts(price, amount, side, tick_decimals);
    self.build_and_sign(token_id, side, maker_amount, taker_amount, "0", neg_risk)
}

/// Computes the Polymarket order ID for a signed CLOB V2 order.
pub fn expected_order_id(
    &self,
    order: &PolymarketOrder,
    neg_risk: bool,
) -> anyhow::Result<VenueOrderId> {
    let hash = order_hash(order, neg_risk)
        .map_err(|e| anyhow::anyhow!("Failed to derive order hash: {e}"))?;
    let order_id = format!("{hash:#x}");
    Ok(VenueOrderId::from(order_id.as_str()))
}

/// Validates a limit order before building, returning a denial reason if invalid.
pub fn validate_limit_order(order: &OrderAny) -> Result<(), String> {
    if order.is_reduce_only() {
        return Err("Reduce-only orders not supported on Polymarket".to_string());
    }

    if order.order_type() != OrderType::Limit {
        return Err(format!(
            "Unsupported order type for Polymarket: {:?}",
            order.order_type()
        ));
    }

    if order.is_quote_quantity() {
        return Err("Quote quantity not supported for limit orders".to_string());
    }

    if order.price().is_none() {
        return Err("Limit orders require a price".to_string());
    }

    if PolymarketOrderType::try_from(order.time_in_force()).is_err() {
        return Err(format!(
            "Unsupported time in force: {:?}",
            order.time_in_force()
        ));
    }

    if PolymarketOrderSide::try_from(order.order_side()).is_err() {
        return Err(format!("Invalid order side: {:?}", order.order_side()));
    }

    if order.is_post_only()
        && !matches!(order.time_in_force(), TimeInForce::Gtc | TimeInForce::Gtd)
    {
        return Err("Post-only orders require GTC or GTD time in force".to_string());
    }

    Ok(())
}

/// Validates a market order before building, returning a denial reason if invalid.
pub fn validate_market_order(order: &OrderAny) -> Result<(), String> {
    if order.is_reduce_only() {
        return Err("Reduce-only orders not supported on Polymarket".to_string());
    }

    if order.order_type() != OrderType::Market {
        return Err(format!(
            "Expected Market order, was {:?}",
            order.order_type()
        ));
    }

pub fn compute_market_maker_taker_amounts(
    price: Decimal,
    amount: Decimal,
    side: PolymarketOrderSide,
    tick_decimals: u32,
) -> (Decimal, Decimal) {
    let precision = tick_decimals + LOT_SIZE_SCALE;
    let amt = amount.trunc_with_scale(LOT_SIZE_SCALE);

    match side {
        PolymarketOrderSide::Buy => {
            let maker_amount = to_fixed_decimal(amt);
            let taker_amount = to_fixed_decimal((amt / price).trunc_with_scale(precision));
            (maker_amount, taker_amount)
        }
        PolymarketOrderSide::Sell => {
            let maker_amount = to_fixed_decimal(amt);
            let taker_amount = to_fixed_decimal((amt * price).trunc_with_scale(precision));
            (maker_amount, taker_amount)
        }
    }
}

/// Generates a random salt for order construction.
///
/// # Panics
///
/// Cannot panic: UUID v4 always produces 16 bytes, so the 8-byte slice conversion is infallible.
pub fn generate_salt() -> u64 {
    let bytes = uuid::Uuid::new_v4().into_bytes();
    u64::from_le_bytes(bytes[..8].try_into().unwrap()) & ((1u64 << 53) - 1)
}

